PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, name TEXT NOT NULL, price INTEGER NOT NULL, stock INTEGER NOT NULL DEFAULT 0, barcode TEXT UNIQUE, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS receipts(id INTEGER PRIMARY KEY, receipt_code TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL, cashier_id INTEGER NOT NULL, total INTEGER NOT NULL, payment_method TEXT NOT NULL, amount_received INTEGER NOT NULL, change_amount INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS receipt_items(id INTEGER PRIMARY KEY, receipt_id INTEGER NOT NULL, product_id INTEGER NOT NULL, product_name TEXT NOT NULL, price INTEGER NOT NULL, quantity INTEGER NOT NULL, subtotal INTEGER NOT NULL);
